./public/index.html:7:async function render(){if(/^\/directory\/?$/.test(location.pathname)){const rows=await request('/api/directory');app.innerHTML=`<button class="back" onclick="location.href='/'">Projects</button><h1>Task directory</h1><label>Project scope <select aria-label="Project scope"><option>Active</option><option>Archived</option></select></label> <label>Task filter <select aria-label="Task filter"><option>All</option><option>Open</option><option>Completed</option><option>Deleted</option></select></label> <label>Priority filter <select aria-label="Priority filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select></label> <label>Directory order <select aria-label="Directory order"><option>Original</option><option>Priority</option><option>Due date</option><option>Title</option></select></label><form class="form"><input aria-label="Directory search"><button>Search directory</button></form><label>Due from <input aria-label="Due from"></label> <label>Due through <input aria-label="Due through"></label> <button class="apply">Apply due range</button><div class="alert-slot" role="status"></div><button type="button" class="complete-visible">Complete visible tasks</button> <button type="button" class="reopen-visible">Reopen visible tasks</button><p class="empty-result" role="status" hidden>No matching tasks</p><section></section>`;let query='',range={from:'',through:''};const scope=app.querySelector('[aria-label="Project scope"]'),tf=app.querySelector('[aria-label="Task filter"]'),pf=app.querySelector('[aria-label="Priority filter"]');function draw(){const matched=rows.filter(t=>(t.archived===(scope.value==='Archived'))&&(tf.value==='Deleted'?t.deleted:!t.deleted&&(tf.value==='All'||(tf.value==='Completed')===t.completed))&&(pf.value==='All'||pf.value===t.priority)&&t.title.replace(/[ \t]+/g,' ').toLowerCase().includes(query.replace(/[ \t]+/g,' ').toLowerCase())&&(!range.from&&!range.through||t.dueDate&&(!range.from||t.dueDate>=range.from)&&(!range.through||t.dueDate<=range.through)));const order=app.querySelector('[aria-label="Directory order"]').value;if(order==='Priority'){const rank={High:0,Normal:1,Low:2};matched.sort((a,b)=>rank[a.priority]-rank[b.priority])}else if(order==='Due date'){matched.sort((a,b)=>!a.dueDate?(!b.dueDate?0:1):!b.dueDate?-1:a.dueDate.localeCompare(b.dueDate))}else if(order==='Title'){matched.sort((a,b)=>{const x=a.title.replace(/[A-Z]/g,c=>c.toLowerCase()),y=b.title.replace(/[A-Z]/g,c=>c.toLowerCase());return x<y?-1:x>y?1:0})}app.querySelector('.empty-result').hidden=matched.length!==0;const eligible=matched.filter(t=>!t.archived&&!t.deleted);const complete=app.querySelector('.complete-visible'),reopen=app.querySelector('.reopen-visible');complete.disabled=scope.value==='Archived'||tf.value==='Deleted'||!eligible.some(t=>!t.completed);reopen.disabled=scope.value==='Archived'||tf.value==='Deleted'||!eligible.some(t=>t.completed);app.querySelector('section').innerHTML=matched.map(t=>`<div class="row" data-testid="directory-task-row"><span data-testid="directory-task-title">${esc(t.title)}</span><span data-testid="directory-project-name">${esc(t.projectName)}</span><span data-testid="directory-task-completion">${t.completed?'Completed':'Open'}</span><span data-testid="directory-task-priority">${esc(t.priority)}</span><span data-testid="directory-task-due-date">${esc(t.dueDate)}</span><span data-testid="directory-task-notes">${esc(t.notes)}</span><button onclick="location.href='/projects/${encodeURIComponent(t.projectId)}'">Open project</button></div>`).join('')}async function bulk(completed){const matched=rows.filter(t=>!t.archived&&!t.deleted&&(scope.value==='Active')&&(tf.value==='All'||(tf.value==='Open'&&!t.completed)||(tf.value==='Completed'&&t.completed))&&(pf.value==='All'||pf.value===t.priority)&&t.title.replace(/[ \\t]+/g,' ').toLowerCase().includes(query.replace(/[ \\t]+/g,' ').toLowerCase())&&(!range.from&&!range.through||t.dueDate&&(!range.from||t.dueDate>=range.from)&&(!range.through||t.dueDate<=range.through))&&(completed?!t.completed:t.completed));await request('/api/directory/bulk',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({completed,ids:matched.map(t=>t.id)})});matched.forEach(t=>t.completed=completed);draw()}app.querySelector('.complete-visible').onclick=()=>bulk(true);app.querySelector('.reopen-visible').onclick=()=>bulk(false);[scope,tf,pf,app.querySelector('[aria-label="Directory order"]')].forEach(x=>x.onchange=draw);app.querySelector('form').onsubmit=e=>{e.preventDefault();query=app.querySelector('[aria-label="Directory search"]').value.trim();draw()};app.querySelector('.apply').onclick=()=>{const from=app.querySelector('[aria-label="Due from"]').value.trim(),through=app.querySelector('[aria-label="Due through"]').value.trim(),valid=value=>{if(!value)return true;const m=value.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return false;const y=+m[1],mo=+m[2],d=+m[3],leap=y%4===0&&(y%100!==0||y%400===0),days=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];return y>=1&&mo>=1&&mo<=12&&d>=1&&d<=days[mo-1]};const alert=app.querySelector('.alert-slot');if(!valid(from)||!valid(through)){alert.innerHTML='<p role="alert">Due range must use valid YYYY-MM-DD dates</p>';return}if(from&&through&&from>through){alert.innerHTML='<p role="alert">Due from must not be after Due through</p>';return}range={from,through};alert.innerHTML='';draw()};draw();return}const match=location.pathname.match(/^\/projects\/([^/]+)\/?$/);if(match){const id=decodeURIComponent(match[1]);let p,tasks,activeProjects;try{p=await request('/api/projects/'+encodeURIComponent(id));tasks=await request(`/api/projects/${encodeURIComponent(id)}/tasks`);activeProjects=await request('/api/projects?filter=Active')}catch{app.innerHTML='<h1>Project not found</h1><button>Projects</button>';app.querySelector('button').onclick=()=>location.href='/';return}
